{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-html-ppt-pitch-deck",
  "title": "Html Ppt Pitch Deck",
  "title_i18n": {
    "zh-CN": "Html Ppt 融资演示",
    "zh-TW": "Html Ppt 募資簡報",
    "ja": "Html Ppt ピッチデック",
    "ko": "Html Ppt 피치덱",
    "de": "Html Ppt Pitch Deck",
    "fr": "Html Ppt Pitch Deck",
    "ru": "Html Ppt питч-дек",
    "es": "Html Ppt Pitch Deck",
    "pt-BR": "Html Ppt Pitch Deck",
    "it": "Html Ppt Pitch Deck",
    "vi": "Html Ppt Pitch Deck",
    "pl": "Html Ppt Pitch Deck",
    "id": "Html Ppt Pitch Deck",
    "nl": "Html Ppt Pitch Deck",
    "ar": "Html Ppt عرض تقديمي",
    "tr": "Html Ppt Pitch Deck",
    "uk": "Html Ppt пітч-дек",
    "en": "Html Ppt Pitch Deck"
  },
  "version": "0.1.0",
  "description": "Investor-ready 10-slide HTML pitch deck — white + blue→purple gradient hero, big numbers, traction bar chart, $4.5M-style ask page. Use when the user wants a fundraising deck, seed-round pitch, or VC meeting slides.",
  "description_i18n": {
    "zh-CN": "投资级 10 页 HTML 融资演示模板——白色 + 蓝紫渐变主视觉，大数字展示，增长柱状图，450 万美元融资需求页。适用于制作融资演示、种子轮路演或 VC 会议幻灯片。",
    "zh-TW": "投資級 10 頁 HTML 募資簡報範本——白色 + 藍紫漸層主視覺，大數字展示，成長長條圖，450 萬美元募資需求頁。適用於製作募資簡報、種子輪路演或 VC 會議簡報。",
    "ja": "投資家向け 10 スライド HTML ピッチデック——白 + 青紫グラデーションのヒーロー、大きな数字、トラクション棒グラフ、450万ドル調達ページ。資金調達デック、シードラウンドピッチ、VC ミーティングスライドに最適。",
    "ko": "투자자용 10슬라이드 HTML 피치덱——화이트 + 블루-퍼플 그라디언트 히어로, 큰 숫자, 트랙션 막대 차트, 450만 달러 투자 유치 페이지. 자금 조달 덱, 시드 라운드 피치, VC 미팅 슬라이드 제작에 사용.",
    "de": "Investoren-fertiges 10-Folien HTML Pitch Deck – weiß + blau-lila Verlauf Hero, große Zahlen, Traction-Balkendiagramm, 4,5-Mio.-$-Ask-Seite. Für Fundraising-Decks, Seed-Round-Pitches oder VC-Meeting-Folien.",
    "fr": "Pitch deck HTML 10 diapositives prêt pour investisseurs – hero blanc + dégradé bleu-violet, grands chiffres, graphique de traction, page de demande 4,5 M$. Pour deck de levée de fonds, pitch seed round ou présentation VC.",
    "ru": "Готовый для инвесторов HTML питч-дек на 10 слайдов – белый + сине-фиолетовый градиент, крупные цифры, график роста, страница запроса $4.5M. Для презентаций по привлечению инвестиций, посевных раундов и встреч с VC.",
    "es": "Pitch deck HTML de 10 diapositivas listo para inversores – hero blanco + gradiente azul-morado, números grandes, gráfico de tracción, página de solicitud de $4.5M. Para decks de financiación, pitch de ronda semilla o reuniones con VC.",
    "pt-BR": "Pitch deck HTML de 10 slides pronto para investidores – hero branco + gradiente azul-roxo, números grandes, gráfico de tração, página de pedido de $4.5M. Para decks de captação, pitch de seed round ou apresentações para VC.",
    "it": "Pitch deck HTML da 10 slide pronto per investitori – hero bianco + gradiente blu-viola, numeri grandi, grafico di trazione, pagina richiesta $4.5M. Per deck di fundraising, pitch seed round o presentazioni VC.",
    "vi": "Bộ pitch deck HTML 10 slide cho nhà đầu tư – hero trắng + gradient xanh-tím, số liệu lớn, biểu đồ tăng trưởng, trang kêu gọi $4.5M. Dùng cho bộ thuyết trình gọi vốn, seed round hoặc họp VC.",
    "pl": "Gotowy dla inwestorów 10-slajdowy HTML pitch deck – biały + gradient niebieski-fioletowy, duże liczby, wykres trakcji, strona z prośbą o $4.5M. Do prezentacji fundraisingowych, pitchy seed round lub spotkań z VC.",
    "id": "Pitch deck HTML 10 slide siap investor – hero putih + gradien biru-ungu, angka besar, grafik batang traksi, halaman permintaan $4.5M. Untuk deck penggalangan dana, pitch seed round, atau slide pertemuan VC.",
    "nl": "Investor-ready HTML pitch deck van 10 slides – wit + blauw-paars verloop hero, grote cijfers, tractie staafdiagram, $4.5M-aanvraagpagina. Voor fundraising decks, seed-round pitches of VC-presentaties.",
    "ar": "عرض تقديمي HTML من 10 شرائح جاهز للمستثمرين – تدرج أبيض + أزرق-بنفسجي، أرقام كبيرة، مخطط نمو، صفحة طلب 4.5 مليون دولار. للعروض التمويلية وعروض الجولة التأسيسية أو اجتماعات VC.",
    "tr": "Yatırımcıya hazır 10 slaytlık HTML pitch deck – beyaz + mavi-mor degrade hero, büyük rakamlar, traksiyon çubuk grafik, $4.5M talep sayfası. Fon toplama sunumları, seed round pitch veya VC toplantı slaytları için.",
    "uk": "Готовий для інвесторів HTML пітч-дек на 10 слайдів – білий + синьо-фіолетовий градієнт, великі цифри, графік зростання, сторінка запиту $4.5M. Для презентацій залучення інвестицій, посівних раундів та зустрічей з VC.",
    "en": "Investor-ready 10-slide HTML pitch deck — white + blue→purple gradient hero, big numbers, traction bar chart, $4.5M-style ask page. Use when the user wants a fundraising deck, seed-round pitch, or VC meeting slides."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/html-ppt-pitch-deck",
  "tags": [
    "example",
    "first-party",
    "deck",
    "finance",
    "web",
    "pitch-deck",
    "pitch",
    "fundraising",
    "seed-round",
    "investor-deck",
    "vc-deck",
    "pitch-slides"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "finance",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Build a 10-slide pitch deck in HTML for my seed round. Use the html-ppt-pitch-deck full-deck template (white + blue→purple gradient, traction bars, $X.XM ask). Confirm three things first: (1) name + one-line pitch, (2) key traction numbers, (3) ask + use of funds.",
        "zh-CN": "使用这个插件完成以下任务：Build a 10-slide pitch deck in HTML for my seed round. Use the html-ppt-pitch-deck full-deck template (white + blue→purple gradient, traction bars, $X.XM ask). Confirm three things first: (1) name + one-line pitch, (2) key traction numbers, (3) ask + use of funds."
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Html Ppt Pitch Deck"
        }
      ]
    },
    "inputs": [
      {
        "name": "one_line_pitch",
        "label": "Name + one-line pitch",
        "type": "text",
        "required": true,
        "placeholder": "Company name and one sentence explaining what it does"
      },
      {
        "name": "key_traction_numbers",
        "label": "Key traction numbers",
        "type": "text",
        "required": true,
        "placeholder": "Revenue, growth, users, pilots, retention, pipeline, or other investor proof"
      },
      {
        "name": "ask_and_use_of_funds",
        "label": "Ask + use of funds",
        "type": "text",
        "required": true,
        "placeholder": "Round size and how the capital will be used"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
